function event(string $bid,string $aid,string $lid,string $st,string $n=''):void{$x=j(EV);$x[]=['id'=>'E'.bin2hex(random_bytes(5)),'branch_id'=>$bid,'assignment_id'=>$aid,'lead_id'=>$lid,'status'=>$st,'note'=>$n,'created_at'=>now()];if(count($x)>25000)$x=array_slice($x,-25000);sj(EV,$x);}
function branchQuota(array $b):int{$q=(int)($b['daily_quota']??0);if($q<=0)$q=(int)(cfg()['daily_quota']??20);return max(1,min(100,$q));}
function branchStats(string $bid):array{$all=array_values(array_filter(j(A),fn($a)=>(string)($a['branch_id']??'')===$bid));$assigned=0;$handled=0;$won=0;foreach($all as $a){$st=(string)($a['status']??'new');if($st==='reassigned')continue;$assigned++;if($st!=='new'){$handled++;if($st==='won')$won++;}}$resp=$assigned?($handled/$assigned):0.0;$conv=$handled?($won/$handled):0.0;$score=$handled<5?50:(int)round(($conv*80)+($resp*20));$score=max(1,min(100,$score));return ['assigned'=>$assigned,'handled'=>$handled,'won'=>$won,'response_rate'=>$resp,'conversion_rate'=>$conv,'score'=>$score];}
function matchArea(array $lead,array $b):bool{$lc=norm((string)($lead['city']??''));$bc=norm((string)($b['city']??''));if($lc!==''&&$bc!==''&&$lc!==$bc)return false;$lr=norm((string)($lead['region']??''));if($lr==='')return true;$br=splitRegions((string)($b['regions']??''));if(!$br)return true;foreach($br as $r)if($r===$lr||str_contains($lr,$r)||str_contains($r,$lr))return true;return false;}
