function recycleExpired():int{$hours=max(1,min(48,(int)(cfg()['unseen_reassign_hours']??3)));$limit=time()-($hours*3600);$as=j(A);$todo=[];$n=0;foreach($as as &$a){if(($a['current']??true)===false||($a['status']??'new')!=='new'||!empty($a['seen_at']))continue;$ts=strtotime((string)($a['created_at']??''));if(!$ts||$ts>$limit)continue;$a['current']=false;$a['status']='reassigned';$a['reassigned_at']=now();$a['updated_at']=now();$todo[]=(string)$a['lead_id'];$n++;}unset($a);if($n)sj(A,$as);foreach($todo as $lid)dispatchLead($lid,previousBranches($lid));return $n;}
function fillQuotas():int{$n=0;$leads=j(L);usort($leads,fn($a,$b)=>strcmp((string)($a['created_at']??''),(string)($b['created_at']??'')));foreach($leads as $l){$id=(string)($l['id']??'');if(!$id||leadLocked($id)||isset($l['active'])&&!$l['active'])continue;if(dispatchLead($id))$n++;}return $n;}
