function headx(string $t):void{echo '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#11151c"><title>'.e($t).' | وب ساز</title><link rel="stylesheet" href="./style.css?v=smart2"></head><body>';}
