function top(array $b=null,bool $adm=false):void{echo '<header class="top"><div class="wrap topin"><a class="brand" href="./"><i>W</i><span>وب ساز<small>سامانه فعالیت نمایندگی</small></span></a><div class="user">'.e($adm?'مدیریت مرکزی':(string)($b['name']??'نمایندگی')).' <a class="btn light sm" href="?action='.($adm?'admin_logout':'logout').'">خروج</a></div></div></header>';}
function nav(string $v,array $b=null,bool $adm=false):void{$it=$adm?['dashboard'=>'نمای کلی','intake'=>'ثبت سفارش','distribution'=>'توزیع هوشمند','branches'=>'نمایندگی‌ها','leads'=>'بانک فرصت‌ها','activity'=>'فعالیت و نتایج','referrals'=>'پاداش معرفی','settings'=>'تنظیمات']:['dashboard'=>'داشبورد','leads'=>'فرصت‌های امروز','followups'=>'پیگیری‌ها','history'=>'سوابق','referrals'=>'معرفی و پاداش','profile'=>'حساب من','help'=>'راهنمای فروش'];echo '<aside class="side"><div class="sidehead"><b>'.e($adm?'مدیریت وب ساز':(string)$b['name']).'</b><small>'.($adm?'کنترل کل سیستم':'کد نمایندگی: '.e((string)$b['code'])).'</small></div>';foreach($it as $k=>$x)echo '<a class="'.($v===$k?'on':'').'" href="?'.($adm?'admin=1&':'').'view='.$k.'">'.$x.'</a>';echo '</aside><nav class="mobile">';foreach($it as $k=>$x)echo '<a class="'.($v===$k?'on':'').'" href="?'.($adm?'admin=1&':'').'view='.$k.'">'.$x.'</a>';echo '</nav>';}
function guide(array $l):string{$biz=e((string)($l['business']?:$l['name']??'کسب‌وکار'));$pr=e((string)($l['proposal']??'طراحی سایت و جذب مشتری'));return '<div class="guide"><div><b>۱. شروع تماس</b><p>'.e((string)($l['script']??'سلام وقت بخیر، از وب ساز تماس می‌گیرم.')).'</p></div><div><b>۲. کشف نیاز</b><p>بپرس: «الان بیشتر مشتری‌ها از چه طریقی شما را پیدا می‌کنند؟» و «مهم‌ترین خدمت یا محصولی که می‌خواهید بیشتر بفروشید چیست؟»</p></div><div><b>۳. پیشنهاد متناسب</b><p>برای '.$biz.' روی '.$pr.' تمرکز کن و نتیجه را ساده توضیح بده.</p></div><div><b>۴. پایان تماس</b><p>حتماً یک اقدام بعدی مشخص کن و نتیجه را همان لحظه ثبت کن.</p></div></div>';}
